def add_model(project_name):
    form = DataModelForm()
    if form.validate_on_submit():
        folder = form.folder.data
        for filename in os.listdir(folder):
            if filename.endswith('.zip'):
                with zipfile.ZipFile(os.path.join(folder, filename), 'r') as zip_ref:
                    zip_ref.extractall(MODEL_FILES)
            else:
                model_filename = secure_filename(filename)
                shutil.copy(os.path.join(folder, filename), MODEL_FILES + model_filename)
        model = DataModel(name=form.name.data,
                          filename=MODEL_FILES + model_filename)
        db.session.add(model)
        db.session.commit()
        flash('Model has successfully been registered!', 'success')
        return redirect(url_for('project', project_name=project.name))

    return render_template('add_data_model.html', form=form)
